<?php require 'includes/boot.php';need();$id=(int)$_POST['id'];$a=$_POST['a']??'';$s=db()->prepare('SELECT * FROM question_papers WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!canAccess($p))die('Forbidden');if($a==='duplicate'&&empty($p['batch_id'])){flash('danger','Choose a batch before duplicating this older paper.');go('papers.php');}
if($a==='finalize'){$m=paperSum($id);if($m['n']<1)flash('danger','No questions.');elseif(abs($m['m']-$p['total_marks'])>0.001&&!$m['a'])flash('danger',"Marks mismatch: {$m['m']} vs {$p['total_marks']}.");else{db()->prepare('UPDATE question_papers SET status="final" WHERE id=?')->execute([$id]);flash('success','Finalized.');}}
elseif($a==='archive'){db()->prepare('UPDATE question_papers SET status="archived" WHERE id=?')->execute([$id]);flash('success','Archived.');}
elseif($a==='delete'){if($p['status']==='final')flash('danger','Finalized papers must be archived, not deleted.');else{$q=db()->prepare('SELECT q.image_path FROM questions q JOIN paper_sections s ON s.id=q.section_id WHERE s.paper_id=?');$q->execute([$id]);$images=$q->fetchAll(PDO::FETCH_COLUMN);db()->prepare('DELETE FROM question_papers WHERE id=?')->execute([$id]);foreach($images as$image){$q=db()->prepare('SELECT 1 FROM questions WHERE image_path=? LIMIT 1');$q->execute([$image]);if(!$q->fetchColumn()&&is_file(__DIR__.'/'.$image))unlink(__DIR__.'/'.$image);}flash('success','Deleted.');}}
elseif($a==='duplicate'){$pdo=db();$newImages=[];$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO question_papers(department_id,class_id,subject_id,batch_id,exam_type,exam_label,exam_date,examiner,total_marks,duration,title,instructions,created_by) SELECT department_id,class_id,subject_id,batch_id,exam_type,exam_label,NULL,examiner,total_marks,duration,title,instructions,? FROM question_papers WHERE id=?')->execute([user()['id'],$id]);$newId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE question_papers SET ref_no=? WHERE id=?')->execute(['QP-'.date('Y').'-'.str_pad((string)$newId,5,'0',STR_PAD_LEFT),$newId]);
 $sections=$pdo->prepare('SELECT * FROM paper_sections WHERE paper_id=? ORDER BY position');$sections->execute([$id]);foreach($sections->fetchAll()as$section){$pdo->prepare('INSERT INTO paper_sections(paper_id,position,title,qtype,attempt_note) VALUES(?,?,?,?,?)')->execute([$newId,$section['position'],$section['title'],$section['qtype'],$section['attempt_note']]);$newSection=(int)$pdo->lastInsertId();
  $questions=$pdo->prepare('SELECT * FROM questions WHERE section_id=? ORDER BY position');$questions->execute([$section['id']]);foreach($questions->fetchAll()as$q){$image=null;if($q['image_path']){$old=__DIR__.'/'.$q['image_path'];$extension=strtolower(pathinfo($q['image_path'],PATHINFO_EXTENSION));if(!in_array($extension,['jpg','jpeg','png','webp'],true)||!is_file($old))throw new RuntimeException('A question image is missing and the paper could not be duplicated.');$name=bin2hex(random_bytes(20)).'.'.$extension;$image='uploads/questions/'.$name;if(!copy($old,__DIR__.'/'.$image))throw new RuntimeException('Could not copy a question image.');$newImages[]=$image;}
   $pdo->prepare('INSERT INTO questions(section_id,position,qtype,body,marks,clo,taxonomy,plo,correct_option,image_path) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$newSection,$q['position'],$q['qtype'],$q['body'],$q['marks'],$q['clo'],$q['taxonomy'],$q['plo'],$q['correct_option'],$image]);$newQuestion=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO question_options(question_id,label,body) SELECT ?,label,body FROM question_options WHERE question_id=?')->execute([$newQuestion,$q['id']]);}}
 $pdo->commit();flash('success','Duplicated as a new draft.');go("paper_form.php?id=$newId");}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();foreach($newImages as$image)if(is_file(__DIR__.'/'.$image))unlink(__DIR__.'/'.$image);error_log($x->getMessage());flash('danger','Duplicate failed. Please retry.');}}
audit($a,"#$id");go('papers.php');
